import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-04-13","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-04-13","date":"2021-04-13T00:00:00.000Z","updated":"2021-04-15T00:00:00.000Z","tags":["Ceph","分布式存储","测试","开发","虚拟IP分配"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-04-13.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-04-13.md","lastUpdated":1780460162000}'),r={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-04-13.md"};function o(n,l,s,h,p,u){return a(),e("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph分布式存储系统的开发与测试" tabindex="-1">会议主题：Ceph分布式存储系统的开发与测试 <a class="header-anchor" href="#会议主题-ceph分布式存储系统的开发与测试" aria-label="Permalink to &quot;会议主题：Ceph分布式存储系统的开发与测试&quot;">​</a></h4><h4 id="参会人员-ceph研发团队成员" tabindex="-1">参会人员：Ceph研发团队成员 <a class="header-anchor" href="#参会人员-ceph研发团队成员" aria-label="Permalink to &quot;参会人员：Ceph研发团队成员&quot;">​</a></h4><h4 id="会议时间-2021年4月13日" tabindex="-1">会议时间：2021年4月13日 <a class="header-anchor" href="#会议时间-2021年4月13日" aria-label="Permalink to &quot;会议时间：2021年4月13日&quot;">​</a></h4><h4 id="会议地点-线上会议" tabindex="-1">会议地点：线上会议 <a class="header-anchor" href="#会议地点-线上会议" aria-label="Permalink to &quot;会议地点：线上会议&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>RGW服务的测试覆盖问题</strong></p><ul><li>会议指出当前Pull Request主要集中在RGW服务上，但缺乏测试覆盖。</li><li>讨论了解决虚拟IP分配问题，以避免与其他节点的IP冲突。</li><li>提出使用bash脚本进行临时解决方案的可能性，但建议寻找更复杂的解决方案。</li></ul></li><li><p><strong>虚拟IP分配问题</strong></p><ul><li>讨论了如何在测试环境中分配虚拟IP，避免冲突。</li><li>提出使用机器锁定机制来分配虚拟IP的建议。</li></ul></li><li><p><strong>RGW服务的测试案例</strong></p><ul><li>计划编写一个测试案例，确保RGW服务能够创建并正确运行。</li><li>需要解决虚拟IP问题，以便进行更全面的测试。</li></ul></li><li><p><strong>单节点部署的测试</strong></p><ul><li>讨论了单节点部署的测试需求，建议创建一个单独的测试目录。</li><li>需要确保单节点部署的测试能够快速运行，并且覆盖所有必要的功能。</li></ul></li><li><p><strong>NFS服务的测试覆盖</strong></p><ul><li>确认了NFS服务的测试已经在DLI测试中覆盖，但建议增加更多的端到端测试。</li><li>讨论了如何改进测试框架，使其更加灵活和自动化。</li></ul></li><li><p><strong>Grafana服务的持久化问题</strong></p><ul><li>讨论了Grafana服务的数据持久化问题，建议暂时使用本地存储，并记录其局限性。</li><li>需要进一步研究如何更好地支持Grafana的定制化需求。</li></ul></li><li><p><strong>NFS服务的CLI参数问题</strong></p><ul><li>决定移除NFS服务的CLI参数，以简化接口。</li><li>需要更新相关的文档和发布说明。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ol><li><p><strong>虚拟IP分配问题的解决方案</strong></p><ul><li>将尝试使用机器锁定机制来分配虚拟IP。</li></ul></li><li><p><strong>RGW服务的测试案例编写</strong></p><ul><li>将编写一个全面的测试案例，确保RGW服务的正确性和稳定性。</li></ul></li><li><p><strong>单节点部署的测试改进</strong></p><ul><li>将创建一个单独的测试目录，以确保单节点部署的测试能够快速且全面地运行。</li></ul></li><li><p><strong>NFS服务的CLI参数移除</strong></p><ul><li>将移除NFS服务的CLI参数，并更新相关的文档和发布说明。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ol><li><p><strong>解决虚拟IP分配问题</strong></p><ul><li>研发团队将探索并实现一个稳定的虚拟IP分配机制。</li></ul></li><li><p><strong>编写并运行RGW服务的测试案例</strong></p><ul><li>研发团队将编写并运行RGW服务的测试案例，确保其功能和性能。</li></ul></li><li><p><strong>改进单节点部署的测试</strong></p><ul><li>研发团队将改进单节点部署的测试，确保其快速且全面地覆盖所有功能。</li></ul></li><li><p><strong>移除并更新NFS服务的CLI参数</strong></p><ul><li>研发团队将移除NFS服务的CLI参数，并更新相关的文档和发布说明。</li></ul></li></ol><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li><p>会议中提到的技术术语和工具，如RGW、Ceph、RADOS、DLI、Grafana等，是Ceph分布式存储系统的关键组件和工具，研发团队将继续深入研究和优化这些组件。</p></li><li><p>会议强调了测试覆盖的重要性和持续改进的必要性，以确保Ceph系统的稳定性和可靠性。</p></li><li><p>研发团队将继续关注用户反馈和系统性能，以不断优化和改进Ceph系统。</p></li></ul>',13)])])}const g=i(r,[["render",o]]);export{c as __pageData,g as default};
